// Vector icons drawn as path data (web inline <svg>, Compose ImageVector, Android vector drawables)
// count as Material Symbols only when every path is the official geometry, unchanged
// (owner decision, 2026-11-17). symbols-paths.json holds hashes of the official paths: the pinned
// google/material-design-icons symbols/web (*.svg) and symbols/android (*.xml) files for Outlined,
// Rounded and Sharp, unfilled and filled, at the default instance (weight 400, grade 0, 24 px). It is
// generated by tools/build/symbols-index.mjs.
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { callArgs, matchClose } from './common.mjs';

const here = dirname(fileURLToPath(import.meta.url));
export const INDEX_FILE = join(here, 'symbols-paths.json');
export const ICON_MAX = 48; // a vector at most this size (dp, px or viewBox units) is an icon

// ---------------------------------------------------------------------------------------------
// Path data: parse SVG / Android pathData into absolute commands, then a canonical string.

const ARGC = { M: 2, L: 2, H: 1, V: 1, C: 6, S: 4, Q: 4, T: 2, A: 7, Z: 0 };

const NUMBER = /[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?/y;
const SEP = /[\s,]*/y;

// SVG path grammar with a cursor, so arc flags written without separators ("a5 5 0 105 5") read
// as single digits.
function parseCommands(d) {
  const s = String(d);
  let i = 0;
  const skip = () => { SEP.lastIndex = i; SEP.exec(s); i = SEP.lastIndex; };
  const number = () => { skip(); NUMBER.lastIndex = i; const m = NUMBER.exec(s); if (!m) return null; i = NUMBER.lastIndex; return Number(m[0]); };
  const flag = () => { skip(); const c = s[i]; if (c !== '0' && c !== '1') return null; i++; return Number(c); };
  const cmds = [];
  skip();
  while (i < s.length) {
    const c = s[i];
    const n = ARGC[c?.toUpperCase()];
    if (n === undefined) return null;
    i++;
    if (n === 0) { cmds.push([c]); skip(); continue; }
    let first = true;
    for (;;) {
      skip();
      if (i >= s.length || /[A-Za-z]/.test(s[i])) break;
      const args = [];
      for (let k = 0; k < n; k++) {
        const v = c.toUpperCase() === 'A' && (k === 3 || k === 4) ? flag() : number();
        if (v === null) return null;
        args.push(v);
      }
      cmds.push([first || c.toUpperCase() !== 'M' ? c : (c === 'M' ? 'L' : 'l'), ...args]);
      first = false;
    }
    if (first) return null;
  }
  return cmds;
}

// [[cmd, ...args]] (relative or absolute) -> absolute M/L/C/Q/A/Z with H/V/S/T expanded.
export function absolutize(cmds) {
  let x = 0, y = 0, sx = 0, sy = 0;
  let lastC = null, lastQ = null;
  const out = [];
  for (const [c, ...a] of cmds) {
    const rel = c === c.toLowerCase();
    const C = c.toUpperCase();
    const ax = v => (rel ? x + v : v);
    const ay = v => (rel ? y + v : v);
    let nextC = null, nextQ = null;
    switch (C) {
      case 'M': x = ax(a[0]); y = ay(a[1]); sx = x; sy = y; out.push(['M', x, y]); break;
      case 'L': x = ax(a[0]); y = ay(a[1]); out.push(['L', x, y]); break;
      case 'H': x = ax(a[0]); out.push(['L', x, y]); break;
      case 'V': y = ay(a[0]); out.push(['L', x, y]); break;
      case 'C': {
        const p = [ax(a[0]), ay(a[1]), ax(a[2]), ay(a[3]), ax(a[4]), ay(a[5])];
        out.push(['C', ...p]); nextC = [p[2], p[3]]; x = p[4]; y = p[5]; break;
      }
      case 'S': {
        const c1 = lastC ? [2 * x - lastC[0], 2 * y - lastC[1]] : [x, y];
        const p = [ax(a[0]), ay(a[1]), ax(a[2]), ay(a[3])];
        out.push(['C', c1[0], c1[1], ...p]); nextC = [p[0], p[1]]; x = p[2]; y = p[3]; break;
      }
      case 'Q': {
        const p = [ax(a[0]), ay(a[1]), ax(a[2]), ay(a[3])];
        out.push(['Q', ...p]); nextQ = [p[0], p[1]]; x = p[2]; y = p[3]; break;
      }
      case 'T': {
        const c1 = lastQ ? [2 * x - lastQ[0], 2 * y - lastQ[1]] : [x, y];
        const p = [ax(a[0]), ay(a[1])];
        out.push(['Q', c1[0], c1[1], ...p]); nextQ = c1; x = p[0]; y = p[1]; break;
      }
      case 'A': {
        const ex = ax(a[5]), ey = ay(a[6]);
        out.push(['A', a[0], a[1], a[2], a[3] ? 1 : 0, a[4] ? 1 : 0, ex, ey]); x = ex; y = ey; break;
      }
      case 'Z': out.push(['Z']); x = sx; y = sy; break;
      default: return null;
    }
    lastC = nextC;
    lastQ = nextQ;
  }
  return out;
}

const num = v => {
  const r = Math.round(v * 1000) / 1000;
  return Object.is(r, -0) ? '0' : String(r);
};

// Canonical text of absolute commands, with y shifted by dy (the web files use viewBox 0 -960 960 960,
// the Android files 0 0 960 960).
export function canonical(abs, dy = 0) {
  return abs.map(([c, ...a]) => {
    if (c === 'Z') return 'Z';
    const v = a.map((n, i) => {
      if (c === 'A') return i === 6 ? n + dy : n; // rx ry rot large sweep x y
      return i % 2 === 1 ? n + dy : n;
    });
    return c + v.map(num).join(',');
  }).join('');
}

export function normalizePath(d) {
  const cmds = parseCommands(d);
  const abs = cmds && absolutize(cmds);
  return abs && abs.length ? abs : null;
}

export const hashOf = text => createHash('sha256').update(text).digest('hex').slice(0, 16);

let INDEX = null;
export function officialIndex() {
  if (INDEX) return INDEX;
  const j = JSON.parse(readFileSync(INDEX_FILE, 'utf8'));
  const buf = Buffer.from(j.hashes, 'base64');
  const set = new Set();
  for (let i = 0; i < buf.length; i += j.hashBytes) set.add(buf.subarray(i, i + j.hashBytes).toString('hex'));
  INDEX = { set, source: j.source };
  return INDEX;
}

// abs: absolute commands (or null when the path could not be read). Official when the canonical
// text, as written or moved between the two official frames, is in the index.
export function isOfficial(abs) {
  if (!abs) return false;
  const { set } = officialIndex();
  return [0, 960, -960].some(dy => set.has(hashOf(canonical(abs, dy))));
}

// ---------------------------------------------------------------------------------------------
// Web: inline <svg> elements.

const attr = (attrs, name) => {
  const m = attrs.match(new RegExp(`(?:^|\\s)${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|\\{\\s*["'\`]([^"'\`]*)["'\`]\\s*\\}|\\{\\s*([\\d.]+)\\s*\\})`, 'i'));
  return m ? (m[1] ?? m[2] ?? m[3] ?? m[4]) : null;
};
const size = v => (v == null ? null : /^\s*([\d.]+)\s*(px)?\s*$/i.test(v) ? parseFloat(v) : null);

// Is this <svg> an icon? viewBox at most 48 units, or the official 960 frame; else width and
// height of at most 48 px; else a class naming an icon. Larger vectors (charts, illustrations) are not.
export function svgIsIcon(attrs) {
  const vb = attr(attrs, 'viewBox');
  if (vb) {
    const n = vb.trim().split(/[\s,]+/).map(Number);
    if (n.length === 4 && n.every(Number.isFinite)) {
      const [, , w, h] = n;
      return (w <= ICON_MAX && h <= ICON_MAX) || (w === 960 && h === 960);
    }
  }
  const w = size(attr(attrs, 'width'));
  const h = size(attr(attrs, 'height'));
  if (w != null && h != null) return w <= ICON_MAX && h <= ICON_MAX;
  return /\bicon\b/i.test(attr(attrs, 'class') ?? attr(attrs, 'className') ?? '');
}

// [{ index, official, paths, problems }] for every icon-like inline <svg> in a source file.
export function webSvgIcons(text) {
  const out = [];
  const re = /<svg\b((?:[^>"'{]|"[^"]*"|'[^']*'|\{[^}]*\})*)>([\s\S]*?)<\/svg\s*>/gi;
  let m;
  while ((m = re.exec(text))) {
    if (!svgIsIcon(m[1])) continue;
    const body = m[2];
    const problems = [];
    const other = body.match(/<(circle|rect|line|polyline|polygon|ellipse|use|image|text|foreignObject)\b/i);
    if (other) problems.push(`<${other[1]}> element (official Symbols are paths only)`);
    const paths = [];
    const pre = /<path\b((?:[^>"'{]|"[^"]*"|'[^']*'|\{[^}]*\})*)\/?>/gi;
    let p;
    while ((p = pre.exec(body))) {
      const d = attr(p[1], 'd');
      const abs = d == null ? null : normalizePath(d);
      paths.push(abs);
      if (!abs) problems.push('a path whose data is not a literal string');
      else if (!isOfficial(abs)) problems.push('a path that is not official Material Symbols geometry');
    }
    if (!paths.length && !other) problems.push('no path');
    out.push({ index: m.index, official: problems.length === 0, paths: paths.length, problems });
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// Compose: ImageVector.Builder / materialIcon blocks; Android: <vector> drawables.

const DSL = {
  moveTo: 'M', moveToRelative: 'm', lineTo: 'L', lineToRelative: 'l',
  horizontalLineTo: 'H', horizontalLineToRelative: 'h', verticalLineTo: 'V', verticalLineToRelative: 'v',
  curveTo: 'C', curveToRelative: 'c', reflectiveCurveTo: 'S', reflectiveCurveToRelative: 's',
  quadTo: 'Q', quadToRelative: 'q', reflectiveQuadTo: 'T', reflectiveQuadToRelative: 't',
  arcTo: 'A', arcToRelative: 'a', close: 'Z',
};

function dslArgs(args) {
  const vals = [];
  for (const raw of args.split(',')) {
    const s = raw.replace(/^\s*\w+\s*=\s*/, '').trim();
    if (!s) continue;
    if (s === 'true' || s === 'false') { vals.push(s === 'true' ? 1 : 0); continue; }
    const n = s.match(/^([-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?)[fFdD]?$/);
    if (!n) return null;
    vals.push(Number(n[1]));
  }
  return vals;
}

// Body of a `path { ... }` DSL block -> absolute commands, or null if any call cannot be read.
export function dslPath(body) {
  const cmds = [];
  const re = /\b(\w+)\s*\(([^()]*)\)/g;
  let m;
  while ((m = re.exec(body))) {
    const c = DSL[m[1]];
    if (!c) continue;
    const args = dslArgs(m[2]);
    if (!args || args.length !== ARGC[c.toUpperCase()]) return null;
    cmds.push([c, ...args]);
  }
  return cmds.length ? absolutize(cmds) : null;
}

const STRING_PATH = /\b(?:addPathNodes|parsePathString|PathParser\(\)\s*\.\s*parsePathString)\s*\(\s*"([^"]*)"/g;

function vectorPaths(region) {
  const paths = [];
  const re = /\b(?:path|materialPath)\s*(?:\([^)]*\))?\s*\{/g;
  let m;
  while ((m = re.exec(region))) {
    const open = m.index + m[0].length - 1;
    const close = matchClose(region, open);
    paths.push(dslPath(region.slice(open + 1, close - 1)));
    re.lastIndex = close;
  }
  for (const s of region.matchAll(STRING_PATH)) paths.push(normalizePath(s[1]));
  return paths;
}

// [{ index, official, paths, problems }] for every Compose ImageVector that is icon-sized.
export function composeVectorIcons(src) {
  const out = [];
  const re = /\bImageVector\.Builder\s*\(|\bmaterialIcon\s*\(/g;
  let m;
  while ((m = re.exec(src))) {
    const call = callArgs(src, m.index);
    let width = null;
    if (call && /^ImageVector/.test(m[0])) {
      const named = call.args.match(/defaultWidth\s*=\s*([\d.]+)f?\s*\.dp/);
      const dps = [...call.args.matchAll(/([\d.]+)f?\s*\.dp/g)].map(x => parseFloat(x[1]));
      width = named ? parseFloat(named[1]) : dps.length ? dps[0] : null;
    }
    if (width != null && width > ICON_MAX) continue;
    const end = src.indexOf('.build()', m.index);
    const stop = /^materialIcon/.test(m[0]) && call ? matchClose(src, src.indexOf('{', call.close)) : end === -1 ? src.length : end;
    const paths = vectorPaths(src.slice(m.index, stop));
    const problems = [];
    if (!paths.length) problems.push('no path');
    paths.forEach(p => {
      if (!p) problems.push('a path that could not be read');
      else if (!isOfficial(p)) problems.push('a path that is not official Material Symbols geometry');
    });
    out.push({ index: m.index, official: problems.length === 0, paths: paths.length, problems });
  }
  return out;
}

// Android vector drawable (res/drawable*/x.xml) -> { index, official, ... } or null if not an icon.
export function xmlVectorIcon(text) {
  const root = text.match(/<vector\b[^>]*>/);
  if (!root) return null;
  const w = root[0].match(/android:width\s*=\s*"([\d.]+)dp"/);
  if (w && parseFloat(w[1]) > ICON_MAX) return null;
  const problems = [];
  const paths = [...text.matchAll(/android:pathData\s*=\s*"([^"]*)"/g)].map(x => normalizePath(x[1]));
  if (!paths.length) problems.push('no path');
  paths.forEach(p => {
    if (!p) problems.push('a path that could not be read');
    else if (!isOfficial(p)) problems.push('a path that is not official Material Symbols geometry');
  });
  return { index: root.index, official: problems.length === 0, paths: paths.length, problems };
}

export const describeProblems = r => [...new Set(r.problems)].join('; ');
